var isDevelopmentModePlanCondition = loadModule('js/conditions/isDevelopmentModePlan.js');

suite('gh-1436 UT — condition script', function () {
    test('path parity: the condition reads exactly the runtime path the module writes', function () {
        var entry = developmentModePlan.planAppendixCliEntry();
        assert.equal(isDevelopmentModePlanCondition.appendixRuntimePath(),
            developmentModePlan.PLAN_APPENDIX_FILE_PATH,
            'condition and module must agree on the materialization path');
        assert.equal(entry.prompt.replace(/^\.\//, ''), isDevelopmentModePlanCondition.appendixRuntimePath(),
            'config prompt path denotes the same file');
    });

    test('plan mode + materialized file → true', function () {
        var path = isDevelopmentModePlanCondition.appendixRuntimePath();
        var files = {};
        files[path] = 'appendix text';
        var fs = fsRecorder(files);
        var captured = captureConsole(function () {
            var ok = isDevelopmentModePlanCondition.action(
                { jobParams: { customParams: { developmentMode: 'plan' } } }, fs);
            assert.equal(ok, true, 'active on a plan leg with the appendix in place');
        });
        assert.equal(captured.logs.length + captured.warns.length, 0, 'condition stays silent');
    });

    test('default / missing mode → false without reading anything', function () {
        var fs = fsRecorder({});
        ['', 'default', 'PLAN', 'adaptive'].forEach(function (mode) {
            var cp = mode === '' ? {} : { developmentMode: mode };
            var ok = isDevelopmentModePlanCondition.action({ jobParams: { customParams: cp } }, fs);
            assert.equal(ok, false, 'mode ' + JSON.stringify(mode) + ' → excluded');
        });
        assert.equal(fs.calls.reads.length, 0, 'non-plan modes never touch the filesystem');
    });

    test('plan mode but file missing/unreadable → false (no dangling prompt read)', function () {
        var fs = fsRecorder({});
        assert.equal(isDevelopmentModePlanCondition.action(
            { jobParams: { customParams: { developmentMode: 'plan' } } }, fs), false, 'missing file → excluded');
        fs.file_read = function () { throw new Error('io error'); };
        assert.equal(isDevelopmentModePlanCondition.action(
            { jobParams: { customParams: { developmentMode: 'plan' } } }, fs), false, 'throwing read → excluded');
    });

    test('teammate and standalone param shapes both resolve customParams', function () {
        var path = isDevelopmentModePlanCondition.appendixRuntimePath();
        var files = {};
        files[path] = 'text';
        var fs = fsRecorder(files);
        assert.equal(isDevelopmentModePlanCondition.action(
            { jobParams: { customParams: { developmentMode: 'plan' } } }, fs), true, 'teammate shape');
        assert.equal(isDevelopmentModePlanCondition.action(
            { customParams: { developmentMode: 'plan' } }, fs), true, 'flat shape');
        assert.equal(isDevelopmentModePlanCondition.action({}, fs), false, 'no params → excluded');
    });
});

